cssCode:
.weather-toggle {
  width: 120px; height: 60px; background: #87ceeb; border-radius: 30px;
  position: relative; cursor: pointer; box-shadow: inset 0 5px 15px rgba(0,0,0,0.1);
  border: 3px solid #fff; overflow: hidden; transition: background 0.5s;
}
.sun-circle {
  width: 46px; height: 46px; background: #ffd700; border-radius: 50%;
  position: absolute; top: 4px; left: 6px; box-shadow: 0 0 15px #ffd700;
  transition: transform 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  display: flex; align-items: center; justify-content: center;
}
.sun-circle::after { 
  content: ''; width: 60px; height: 60px; border: 3px dashed #ffa500; 
  border-radius: 50%; position: absolute; animation: spinSun 6s linear infinite; 
}
.weather-toggle.night { background: #191970; }
.weather-toggle.night .sun-circle { transform: translateX(56px); background: #f4f4f9; box-shadow: 0 0 15px #f4f4f9; }
.weather-toggle.night .sun-circle::after { border-color: transparent; }
@keyframes spinSun { 100% { transform: rotate(360deg); } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const toggle = document.createElement('div');
toggle.className = 'weather-toggle';

const sun = document.createElement('div');
sun.className = 'sun-circle';

toggle.appendChild(sun);
c.appendChild(toggle);

toggle.addEventListener('click', () => {
  toggle.classList.toggle('night');
});
